(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, FINISH = 4200, FOCAL = 900, HORIZON = 195;
  canvas.width = W; canvas.height = H;
  const $ = (id) => document.getElementById(id);
  const ui = {speed:$('speed'),gear:$('gear'),distance:$('distance'),progress:$('progress'),clock:$('clock'),overlay:$('overlay'),intro:$('introCard'),result:$('resultCard'),callout:$('calloutText'),surface:$('surface')};
  const state = {running:false,done:false,dist:0,speed:0,lane:0,laneVelocity:0,time:0,steer:0,brake:false,accelerate:false,keys:{},sound:true,shake:0,last:0,calloutUntil:0,engine:null};
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const mix=(a,b,t)=>a+(b-a)*t;
  const fract=(n)=>n-Math.floor(n);
  const hash=(n)=>fract(Math.sin(n*127.1+311.7)*43758.5453);
  const curveAt=(d)=>0.58*Math.sin(d/710)+0.34*Math.sin(d/365+1.4)+0.22*Math.sin(d/1330+2.7);
  const hillAt=(d)=>32*Math.sin(d/540)+19*Math.sin(d/260+2.2);
  const pathX=(d)=>{let x=0,steps=Math.max(1,Math.floor(d/24));for(let i=1;i<=steps;i++)x+=curveAt(i*24)*0.63;return x;};
  const horizonAt=(d)=>HORIZON+hillAt(d)*.24;
  const project=(z,worldX,baseY=0)=>{const scale=FOCAL/(z+180);return {x:W*.5+(worldX-state.lane)*scale,y:horizonAt(state.dist+z)+(120-baseY)*scale,s:scale};};
  const racers=[{at:540,lane:-.38,speed:73,color:'#d64d36',num:'07'},{at:1060,lane:.37,speed:79,color:'#d7d2bd',num:'12'},{at:1830,lane:-.18,speed:86,color:'#dfb13e',num:'03'}];
  let stars=[];for(let i=0;i<100;i++)stars.push({x:hash(i+1)*W,y:hash(i+271)*175,r:.4+hash(i+571)*1.1,a:.25+hash(i+721)*.6});
  const segments=[];
  for(let i=0;i<64;i++){const z=i*75;segments.push({z,curve:curveAt(z),hill:hillAt(z),seed:i});}

  function roundedRect(x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();}
  function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill();}
  function drawSky(){
    const grad=ctx.createLinearGradient(0,0,0,HORIZON+25);grad.addColorStop(0,'#090d1a');grad.addColorStop(.58,'#172235');grad.addColorStop(1,'#66705e');ctx.fillStyle=grad;ctx.fillRect(0,0,W,HORIZON+38);
    for(const s of stars){ctx.globalAlpha=s.a;ctx.fillStyle='#e3e5dc';ctx.fillRect(s.x,s.y,s.r,s.r);}ctx.globalAlpha=1;
    const moonX=742-(pathX(state.dist)*.14%90), moonY=82;ctx.fillStyle='rgba(233,236,205,.08)';ctx.beginPath();ctx.arc(moonX,moonY,35,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e2e5cf';ctx.beginPath();ctx.arc(moonX,moonY,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a6ae9f';ctx.beginPath();ctx.arc(moonX+6,moonY-4,15,0,Math.PI*2);ctx.fill();
    // Layered, distant pine ridges.
    for(let layer=0;layer<3;layer++){const y=HORIZON-10+layer*11;ctx.beginPath();ctx.moveTo(0,HORIZON+35);for(let x=0;x<=W;x+=16){const n=Math.sin(x*.018+layer*2.7+state.dist*.0002)*10+Math.sin(x*.043+layer)*5;ctx.lineTo(x,y+n+layer*3);}ctx.lineTo(W,HORIZON+40);ctx.closePath();ctx.fillStyle=['#17202a','#111a21','#10171d'][layer];ctx.fill();}
    const haze=ctx.createLinearGradient(0,HORIZON,0,HORIZON+90);haze.addColorStop(0,'rgba(169,177,142,.15)');haze.addColorStop(1,'rgba(120,136,115,0)');ctx.fillStyle=haze;ctx.fillRect(0,HORIZON,W,90);
  }
  function projectRoad(z){const center=pathX(state.dist+z)-pathX(state.dist);const p=project(z,center);const width=150*p.s;return {x:p.x,y:p.y,width,scale:p.s};}
  function drawTerrain(){
    ctx.fillStyle='#26312c';ctx.fillRect(0,HORIZON,W,H-HORIZON);
    for(let i=segments.length-1;i>=0;i--){const z=segments[i].z;if(z>2200)continue;const near=drawRoadSegment(z,z+75,segments[i].seed);drawTrees(z,z+75,segments[i].seed,near);}
  }
  function drawRoadSegment(z1,z2,id){
    const a=projectRoad(z1),b=projectRoad(z2);if(a.y>H+30||b.y<HORIZON-10)return a;
    const shade=(id+Math.floor(state.dist/75))%2;
    // verge, gravel shoulder, and rutted road
    polygon([[W/2+(pathX(state.dist+z1)-pathX(state.dist)-212)*a.scale,a.y],[W/2+(pathX(state.dist+z2)-pathX(state.dist)-212)*b.scale,b.y],[W/2+(pathX(state.dist+z2)-pathX(state.dist)+212)*b.scale,b.y],[W/2+(pathX(state.dist+z1)-pathX(state.dist)+212)*a.scale,a.y]],shade?'#28332d':'#2b362f');
    const shoulder1= a.width*1.12,shoulder2=b.width*1.12;
    polygon([[a.x-shoulder1,a.y],[b.x-shoulder2,b.y],[b.x+shoulder2,b.y],[a.x+shoulder1,a.y]],shade?'#79664a':'#66583f');
    polygon([[a.x-a.width,a.y],[b.x-b.width,b.y],[b.x+b.width,b.y],[a.x+a.width,a.y]],shade?'#927851':'#856e49');
    // Light catches the left rut; small gravel strokes lend the road texture.
    ctx.strokeStyle=shade?'rgba(214,184,122,.24)':'rgba(226,201,146,.2)';ctx.lineWidth=Math.max(.5,b.scale*1.8);ctx.beginPath();ctx.moveTo(a.x-a.width*.47,a.y);ctx.lineTo(b.x-b.width*.47,b.y);ctx.moveTo(a.x+a.width*.49,a.y);ctx.lineTo(b.x+b.width*.49,b.y);ctx.stroke();
    if(id%2===0&&b.y-a.y>1){ctx.fillStyle='rgba(39,34,27,.19)';const seed=hash(id+Math.floor(state.dist/75));for(let k=0;k<4;k++){const x=mix(a.x,b.x,hash(k+id*9))*1;const y=mix(a.y,b.y,hash(k+id*4));const w=Math.max(.5,b.scale*(3+hash(k+id)*4));ctx.fillRect(x-w,y,w*1.7,Math.max(1,b.scale*1.2));}}
    // Repeating reflective edge stakes, like an old rally night stage.
    if(id%2===0){for(const side of [-1,1]){const postW=Math.max(1,b.scale*3);const postH=Math.max(2,b.scale*13);const x=b.x+side*b.width*1.17;ctx.fillStyle='rgba(226,224,192,.8)';ctx.fillRect(x-postW/2,b.y-postH,postW,postH);ctx.fillStyle='#c65d45';ctx.fillRect(x-postW/2,b.y-postH,postW,postH*.28);}}
    return a;
  }
  function drawTrees(z1,z2,id){
    // Forest walls recede and move against the car, with silhouettes sized by perspective.
    for(const side of [-1,1]){const seed=id*2+(side>0?1:0);if(hash(seed+77)>.75)continue;const z=z1+hash(seed+91)*(z2-z1);if(z<65)continue;const center=pathX(state.dist+z)-pathX(state.dist),p=project(z,center+side*(265+hash(seed+55)*245));if(p.y>HORIZON+205||p.y<HORIZON-30)continue;const size=clamp(p.s*(48+hash(seed+23)*40),2,125);const sway=Math.sin(state.time*.8+seed)*size*.025;const x=p.x+sway,y=p.y;
      polygon([[x-size*.19,y],[x,y-size*1.32],[x+size*.19,y]],'#101a1c');polygon([[x-size*.29,y-size*.31],[x,y-size*1.58],[x+size*.29,y-size*.31]],'#142020');polygon([[x-size*.4,y-size*.63],[x,y-size*1.88],[x+size*.4,y-size*.63]],'#192522');ctx.fillStyle='#181b17';ctx.fillRect(x-size*.045,y-size*.1,size*.09,size*.28);
      if(size>24){ctx.fillStyle='rgba(220,194,131,.58)';ctx.fillRect(x-size*.34,y-size*.42,Math.max(1,size*.045),size*.09);}
    }
  }
  function drawRacer(r){
    const z=r.at-state.dist;if(z<20||z>1450)return;const xcenter=pathX(r.at)-pathX(state.dist)+r.lane*150,p=project(z,xcenter);const scale=p.s;const w=clamp(scale*40,5,85),h=w*.56;const x=p.x,y=p.y;
    // Dust wake catches the headlights behind each rival.
    const dust=ctx.createRadialGradient(x,y,1,x,y,w*1.7);dust.addColorStop(0,'rgba(185,166,121,.15)');dust.addColorStop(1,'rgba(185,166,121,0)');ctx.fillStyle=dust;ctx.fillRect(x-w*2,y-h*2,w*4,h*3);
    polygon([[x-w*.58,y],[x-w*.46,y-h*.54],[x-w*.2,y-h*.78],[x+w*.25,y-h*.78],[x+w*.48,y-h*.48],[x+w*.58,y]],'#171916');polygon([[x-w*.34,y-h*.48],[x-w*.16,y-h*.72],[x+w*.17,y-h*.72],[x+w*.35,y-h*.46]],'#59615b');polygon([[x-w*.56,y-h*.18],[x-w*.52,y],[x+w*.52,y],[x+w*.57,y-h*.18]],r.color);
    ctx.fillStyle='#ed6045';ctx.fillRect(x-w*.48,y-h*.2,w*.13,h*.11);ctx.fillRect(x+w*.35,y-h*.2,w*.13,h*.11);ctx.fillStyle='#222';ctx.fillRect(x-w*.38,y-h*.03,w*.76,h*.09);ctx.fillStyle='#f0e2b9';ctx.font=`${clamp(w*.19,5,10)}px monospace`;ctx.textAlign='center';ctx.fillText(r.num,x,y-h*.22);
  }
  function drawHeadlights(){
    const x=W/2-state.lane*(FOCAL/300),beam=ctx.createLinearGradient(x,HORIZON+110,x,HORIZON+310);beam.addColorStop(0,'rgba(224,220,174,0)');beam.addColorStop(.55,'rgba(228,217,167,.075)');beam.addColorStop(1,'rgba(241,230,179,.21)');polygon([[x-25,HORIZON+95],[x-280,H+40],[x+280,H+40],[x+25,HORIZON+95]],'rgba(234,221,167,.065)');ctx.fillStyle=beam;ctx.fillRect(x-180,HORIZON+90,360,260);
  }
  function drawCockpit(){
    const shake=state.shake;ctx.save();ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);
    // Bonnet and front wheel arches frame the road, unmistakably in-car.
    polygon([[0,430],[82,410],[205,421],[337,447],[480,457],[623,447],[755,421],[878,410],[960,430],[960,540],[0,540]],'#222422');
    polygon([[0,467],[115,439],[216,447],[330,470],[480,480],[630,470],[744,447],[845,439],[960,467],[960,540],[0,540]],'#181b1a');
    ctx.strokeStyle='rgba(187,177,138,.42)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(58,461);ctx.lineTo(216,440);ctx.lineTo(349,465);ctx.moveTo(902,461);ctx.lineTo(744,440);ctx.lineTo(611,465);ctx.stroke();
    // Rally cockpit instrument panel
    polygon([[0,480],[180,464],[780,464],[960,480],[960,540],[0,540]],'#101314');ctx.fillStyle='#343632';ctx.fillRect(0,477,W,2);
    // left gauge cluster, glowing analog dials
    for(let g=0;g<2;g++){const cx=112+g*88,cy=510,r=25;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle='#0a0d0e';ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#777364';ctx.stroke();ctx.beginPath();ctx.arc(cx,cy,r-4,Math.PI*.78,Math.PI*2.18);ctx.strokeStyle='#d5d0bd';ctx.lineWidth=1;ctx.stroke();for(let t=0;t<6;t++){const a=Math.PI*.82+t*.26;ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*17,cy+Math.sin(a)*17);ctx.lineTo(cx+Math.cos(a)*21,cy+Math.sin(a)*21);ctx.strokeStyle='#ded9c8';ctx.stroke();}const turn=(state.speed/180)*1.45;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(Math.PI*1.9+turn)*16,cy+Math.sin(Math.PI*1.9+turn)*16);ctx.strokeStyle='#d95d46';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#85877f';ctx.font='6px monospace';ctx.textAlign='center';ctx.fillText(g?'RPM ×1000':'KM/H',cx,cy+15);}
    // center console and green status lamps
    roundedRect(390,486,180,34,3,'#1c2020');ctx.fillStyle='#414640';ctx.fillRect(402,492,156,1);ctx.fillStyle='#d9f36a';ctx.fillRect(414,502,5,3);ctx.fillStyle='#d86c54';ctx.fillRect(426,502,5,3);ctx.fillStyle='#d9f36a';ctx.fillRect(438,502,5,3);ctx.fillStyle='#a4aaa0';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText('LANCIA  ·  4WD',480,515);
    // wheel, spokes and hand grip
    ctx.beginPath();ctx.ellipse(480,557,143,83,0,Math.PI,Math.PI*2);ctx.strokeStyle='#090b0b';ctx.lineWidth=18;ctx.stroke();ctx.beginPath();ctx.ellipse(480,557,143,83,0,Math.PI,Math.PI*2);ctx.strokeStyle='#4b4d48';ctx.lineWidth=2;ctx.stroke();polygon([[467,495],[493,495],[516,536],[504,540],[480,517],[456,540],[444,536]],'#343936');ctx.restore();
  }
  function render(){
    ctx.clearRect(0,0,W,H);drawSky();drawTerrain();drawHeadlights();for(const r of racers)drawRacer(r);drawCockpit();
    if(state.speed>75){ctx.globalAlpha=clamp((state.speed-75)/160,0,.24);ctx.strokeStyle='#c7c9ae';ctx.lineWidth=1;for(let i=0;i<7;i++){const x=hash(i+Math.floor(state.time*9))*W;const y=HORIZON+120+hash(i+88)*250;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(x<W/2?-1:1)*12,y+30);ctx.stroke();}ctx.globalAlpha=1;}
  }

