  function updateHUD(){
    const kmh=Math.round(state.speed);ui.speed.textContent=String(kmh).padStart(3,'0');ui.gear.textContent=kmh<5?'N':String(clamp(Math.floor(kmh/32)+1,1,6));ui.distance.textContent=Math.max(0,(FINISH-state.dist)/1000).toFixed(1);ui.progress.style.width=`${Math.min(100,state.dist/FINISH*100)}%`;const t=state.time;ui.clock.textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}.${String(Math.floor(t%1*100)).padStart(2,'0')}`;
    const curve=Math.abs(curveAt(state.dist+250));ui.surface.textContent=curve>.55?'BENDS':state.speed>100?'FAST':'LOOSE';
  }
  function beep(freq,duration,volume=.05){if(!state.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!state.engine){state.engine=new AC();state.osc=state.engine.createOscillator();state.gain=state.engine.createGain();state.osc.type='sawtooth';state.osc.frequency.value=70;state.gain.gain.value=0;state.osc.connect(state.gain);state.gain.connect(state.engine.destination);state.osc.start();}state.engine.resume();state.osc.frequency.setTargetAtTime(freq,state.engine.currentTime,.08);state.gain.gain.setTargetAtTime(volume,state.engine.currentTime,.04);if(duration<1)state.gain.gain.setTargetAtTime(0,state.engine.currentTime+duration,.1);}catch(_){}}
  function finish(){state.running=false;state.done=true;ui.result.classList.remove('hidden');$('finalTime').textContent=ui.clock.textContent;$('resultTitle').innerHTML=state.time<180?'NIGHT<br><em>DRIVER</em>':'STAGE<br><em>SURVIVOR</em>';ui.overlay.classList.remove('dismissed');beep(480,.35,.08);}
  function frame(now){if(!state.last)state.last=now;const dt=Math.min(.04,(now-state.last)/1000);state.last=now;if(state.running){state.time+=dt;const accelerate=state.keys.ArrowUp||state.keys.KeyW||state.accelerate,brake=state.keys.ArrowDown||state.keys.KeyS||state.brake,left=state.keys.ArrowLeft||state.keys.KeyA||state.steer<-.2,right=state.keys.ArrowRight||state.keys.KeyD||state.steer>.2;const target=accelerate?154:0;state.speed+=((target-state.speed)*(accelerate?.29:.12)*dt*7);if(brake)state.speed=Math.max(0,state.speed-125*dt);state.speed=clamp(state.speed,0,180);
      const steer=(left?-1:0)+(right?1:0);state.laneVelocity+=steer*1.55*dt;state.laneVelocity*=Math.pow(.08,dt);state.lane+=state.laneVelocity*dt*(.55+state.speed/95);state.lane=clamp(state.lane,-2.9,2.9);const edge=Math.max(0,Math.abs(state.lane)-1.12);if(edge>0){state.speed=Math.max(18,state.speed-(15+edge*15)*dt);state.shake=5+edge*3;}else state.shake=state.speed>95?1.6:0;state.dist+=state.speed/3.6*dt;for(const r of racers)if(state.dist>r.at-50&&state.dist<r.at+8){r.at+=r.speed/3.6*dt;if(r.at>state.dist+20)r.at=state.dist-80;}if(state.dist>=FINISH){state.dist=FINISH;finish();}if(state.speed>8)beep(66+state.speed*1.2,.3,.012);updateHUD();
      if(state.dist>100&&state.calloutUntil<state.time){ui.callout.textContent=Math.abs(curveAt(state.dist+190))>.6?'CAUTION · TIGHT CORNER':'KEEP IT FLAT · GRAVEL';state.calloutUntil=state.time+5;setTimeout(()=>{if(state.running)ui.callout.textContent='NIGHT STAGE · GRAVEL';},1800);}}
    render();requestAnimationFrame(frame);
  }
  function start(){if(state.done){state.dist=0;state.time=0;state.speed=0;state.lane=0;state.laneVelocity=0;state.done=false;racers[0].at=540;racers[1].at=1060;racers[2].at=1830;ui.result.classList.add('hidden');}state.running=true;state.last=performance.now();ui.overlay.classList.add('dismissed');ui.callout.textContent='NIGHT STAGE · GRAVEL';beep(100,.6,.055);}
  $('startButton').addEventListener('click',start);$('restartButton').addEventListener('click',start);
  $('soundButton').addEventListener('click',()=>{state.sound=!state.sound;$('soundButton').classList.toggle('muted',!state.sound);$('soundButton').querySelector('b').textContent=state.sound?'ON':'OFF';if(!state.sound&&state.gain)state.gain.gain.setTargetAtTime(0,state.engine.currentTime,.08);});
  window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();state.keys[e.code]=true;if(e.code==='Enter'&&!state.running)start();});window.addEventListener('keyup',e=>{state.keys[e.code]=false;});window.addEventListener('blur',()=>{state.keys={};state.accelerate=false;state.brake=false;state.steer=0;});
  document.querySelectorAll('.mobile-controls button').forEach(button=>{const name=button.dataset.control;const down=e=>{e.preventDefault();if(name==='left')state.steer=-1;if(name==='right')state.steer=1;if(name==='brake')state.brake=true;if(name==='accelerate')state.accelerate=true;};const up=e=>{e.preventDefault();if(name==='left'&&state.steer<0||name==='right'&&state.steer>0)state.steer=0;if(name==='brake')state.brake=false;if(name==='accelerate')state.accelerate=false;};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);});
  requestAnimationFrame(frame);
})();

