2:   function beep(freq,duration,volume=.05){if(!state.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!state.engine){state.engine=new AC();state.osc=state.engine.createOscillator();state.gain=state.engine.createGain();state.osc.type='sawtooth';state.osc.frequency.value=70;state.gain.gain.value=0;state.osc.connect(state.gain);state.gain.connect(state.engine.destination);state.osc.start();}state.engine.resume();state.osc.frequency.setTargetAtTime(freq,state.engine.currentTime,.08);state.gain.gain.setTargetAtTime(volume,state.engine.currentTime,.04);if(duration<1)state.gain.gain.setTargetAtTime(0,state.engine.currentTime+duration,.1);}catch(_){}}
3:   function finish(){state.running=false;state.done=true;ui.result.classList.remove('hidden');$('finalTime').textContent=ui.clock.textContent;$('resultTitle').innerHTML=state.time<180?'NIGHT<br><em>DRIVER</em>':'STAGE<br><em>SURVIVOR</em>';ui.overlay.classList.remove('dismissed');beep(480,.35,.08);}
4:   function frame(now){if(!state.last)state.last=now;const dt=Math.min(.04,(now-state.last)/1000);state.last=now;if(state.running){state.time+=dt;const accelerate=state.keys.ArrowUp||state.keys.KeyW||state.accelerate,brake=state.keys.ArrowDown||state.keys.KeyS||state.brake,left=state.keys.ArrowLeft||state.keys.KeyA||state.steer<-.2,right=state.keys.ArrowRight||state.keys.KeyD||state.steer>.2;const target=accelerate?154:0;state.speed+=(target-state.speed)*(accelerate?.29:.12)*dt*7;if(brake)state.speed=Math.max(0,state.speed-125*dt);state.speed=clamp(state.speed,0,180);const steer=(left?-1:0)+(right?1:0);state.laneVelocity+=steer*1.55*dt;state.laneVelocity*=Math.pow(.08,dt);state.lane+=state.laneVelocity*dt*(.55+state.speed/95);state.lane=clamp(state.lane,-2.9,2.9);const edge=Math.max(0,Math.abs(state.lane)-1.12);if(edge>0){state.speed=Math.max(18,state.speed-(15+edge*15)*dt);state.shake=5+edge*3;}else state.shake=state.speed>95?1.6:0;state.dist+=state.speed/3.6*dt;for(const r of racers)if(state.dist>r.at-50&&state.dist<r.at+8){r.at+=r.speed/3.6*dt;if(r.at>state.dist+20)r.at=state.dist-80;}if(state.dist>=FINISH){state.dist=FINISH;finish();}if(state.speed>8)beep(66+state.speed*1.2,.3,.012);updateHUD();if(state.dist>100&&state.calloutUntil<state.time){ui.callout.textContent=Math.abs(curveAt(state.dist+190))>.6?'CAUTION · TIGHT CORNER':'KEEP IT FLAT · GRAVEL';state.calloutUntil=state.time+5;setTimeout(()=>{if(state.running)ui.callout.textContent='NIGHT STAGE · GRAVEL';},1800);}}render();requestAnimationFrame(frame);}
5:   function start(){if(state.done){state.dist=0;state.time=0;state.speed=0;state.lane=0;state.laneVelocity=0;state.done=false;racers[0].at=540;racers[1].at=1060;racers[2].at=1830;ui.result.classList.add('hidden');}state.running=true;state.last=performance.now();ui.overlay.classList.add('dismissed');ui.callout.textContent='NIGHT STAGE · GRAVEL';beep(100,.6,.055);}
