const state={running:false,done:false,dist:0,speed:0,lane:0,laneVelocity:0,time:0,steer:0,brake:false,accelerate:false,keys:{},sound:true,shake:0,last:0,calloutUntil:0,engine:null};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),fract=n=>n-Math.floor(n),hash=n=>fract(Math.sin(n*127.1+311.7)*43758.5453);
