const racers=[{at:540,lane:-.38,speed:73,color:'#d64d36',num:'07'},{at:1060,lane:.37,speed:79,color:'#d7d2bd',num:'12'},{at:1830,lane:-.18,speed:86,color:'#dfb13e',num:'03'}];
const stars=Array.from({length:100},(_,i)=>({x:hash(i+1)*W,y:hash(i+271)*175,r:.4+hash(i+571)*1.1,a:.25+hash(i+721)*.6}));
const segments=Array.from({length:64},(_,i)=>({z:i*75,seed:i}));
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill();}
function drawSky(){
 const grad=ctx.createLinearGradient(0,0,0,HORIZON+25);grad.addColorStop(0,'#090d1a');grad.addColorStop(.58,'#172235');grad.addColorStop(1,'#66705e');ctx.fillStyle=grad;ctx.fillRect(0,0,W,HORIZON+38);
 for(const s of stars){ctx.globalAlpha=s.a;ctx.fillStyle='#e3e5dc';ctx.fillRect(s.x,s.y,s.r,s.r);}ctx.globalAlpha=1;
 const mx=742-(pathX(state.dist)*.14%90),my=82;ctx.fillStyle='rgba(233,236,205,.08)';ctx.beginPath();ctx.arc(mx,my,35,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e2e5cf';ctx.beginPath();ctx.arc(mx,my,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a6ae9f';ctx.beginPath();ctx.arc(mx+6,my-4,15,0,Math.PI*2);ctx.fill();
 for(let layer=0;layer<3;layer++){const y=HORIZON-10+layer*11;ctx.beginPath();ctx.moveTo(0,HORIZON+35);for(let x=0;x<=W;x+=16)ctx.lineTo(x,y+Math.sin(x*.018+layer*2.7+state.dist*.0002)*10+Math.sin(x*.043+layer)*5+layer*3);ctx.lineTo(W,HORIZON+40);ctx.closePath();ctx.fillStyle=['#17202a','#111a21','#10171d'][layer];ctx.fill();}
 const haze=ctx.createLinearGradient(0,HORIZON,0,HORIZON+90);haze.addColorStop(0,'rgba(169,177,142,.15)');haze.addColorStop(1,'rgba(120,136,115,0)');ctx.fillStyle=haze;ctx.fillRect(0,HORIZON,W,90);
}
function projectRoad(z){const center=pathX(state.dist+z)-pathX(state.dist),p=project(z,center);return{x:p.x,y:p.y,width:150*p.s,scale:p.s};}
function drawRoadSegment(z1,z2,id){
 const a=projectRoad(z1),b=projectRoad(z2);if(a.y>H+30||b.y<HORIZON-10)return a;const shade=(id+Math.floor(state.dist/75))%2;
 polygon([[W/2+(pathX(state.dist+z1)-pathX(state.dist)-212)*a.scale,a.y],[W/2+(pathX(state.dist+z2)-pathX(state.dist)-212)*b.scale,b.y],[W/2+(pathX(state.dist+z2)-pathX(state.dist)+212)*b.scale,b.y],[W/2+(pathX(state.dist+z1)-pathX(state.dist)+212)*a.scale,a.y]],shade?'#28332d':'#2b362f');
 const sh1=a.width*1.12,sh2=b.width*1.12;polygon([[a.x-sh1,a.y],[b.x-sh2,b.y],[b.x+sh2,b.y],[a.x+sh1,a.y]],shade?'#79664a':'#66583f');polygon([[a.x-a.width,a.y],[b.x-b.width,b.y],[b.x+b.width,b.y],[a.x+a.width,a.y]],shade?'#927851':'#856e49');
 ctx.strokeStyle=shade?'rgba(214,184,122,.24)':'rgba(226,201,146,.2)';ctx.lineWidth=Math.max(.5,b.scale*1.8);ctx.beginPath();ctx.moveTo(a.x-a.width*.47,a.y);ctx.lineTo(b.x-b.width*.47,b.y);ctx.moveTo(a.x+a.width*.49,a.y);ctx.lineTo(b.x+b.width*.49,b.y);ctx.stroke();
 if(id%2===0)for(const side of[-1,1]){const pw=Math.max(1,b.scale*3),ph=Math.max(2,b.scale*13),x=b.x+side*b.width*1.17;ctx.fillStyle='rgba(226,224,192,.8)';ctx.fillRect(x-pw/2,b.y-ph,pw,ph);ctx.fillStyle='#c65d45';ctx.fillRect(x-pw/2,b.y-ph,pw,ph*.28);}return a;
}
function drawTrees(z1,z2,id){for(const side of[-1,1]){const seed=id*2+(side>0?1:0);if(hash(seed+77)>.75)continue;const z=z1+hash(seed+91)*(z2-z1);if(z<65)continue;const center=pathX(state.dist+z)-pathX(state.dist),p=project(z,center+side*(265+hash(seed+55)*245));if(p.y>HORIZON+205||p.y<HORIZON-30)continue;const size=Math.min(125,p.s*(48+hash(seed+23)*40)),x=p.x+Math.sin(state.time*.8+seed)*size*.025,y=p.y;polygon([[x-size*.19,y],[x,y-size*1.32],[x+size*.19,y]],'#101a1c');polygon([[x-size*.29,y-size*.31],[x,y-size*1.58],[x+size*.29,y-size*.31]],'#142020');polygon([[x-size*.4,y-size*.63],[x,y-size*1.88],[x+size*.4,y-size*.63]],'#192522');ctx.fillStyle='#181b17';ctx.fillRect(x-size*.045,y-size*.1,size*.09,size*.28);if(size>24){ctx.fillStyle='rgba(220,194,131,.58)';ctx.fillRect(x-size*.34,y-size*.42,Math.max(1,size*.045),size*.09);}}}
function drawTerrain(){ctx.fillStyle='#26312c';ctx.fillRect(0,HORIZON,W,H-HORIZON);for(let i=segments.length-1;i>=0;i--){const z=segments[i].z;if(z>2200)continue;drawRoadSegment(z,z+75,segments[i].seed);drawTrees(z,z+75,segments[i].seed);}}

