 for(let g=0;g<2;g++){const cx=112+g*88,cy=510,r=25;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle='#0a0d0e';ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#777364';ctx.stroke();ctx.beginPath();ctx.arc(cx,cy,r-4,Math.PI*.78,Math.PI*2.18);ctx.strokeStyle='#d5d0bd';ctx.lineWidth=1;ctx.stroke();for(let t=0;t<6;t++){const a=Math.PI*.82+t*.26;ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*17,cy+Math.sin(a)*17);ctx.lineTo(cx+Math.cos(a)*21,cy+Math.sin(a)*21);ctx.strokeStyle='#ded9c8';ctx.stroke();}const turn=state.speed/180*1.45;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(Math.PI*1.9+turn)*16,cy+Math.sin(Math.PI*1.9+turn)*16);ctx.strokeStyle='#d95d46';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#85877f';ctx.font='6px monospace';ctx.textAlign='center';ctx.fillText(g?'RPM ×1000':'KM/H',cx,cy+15);}
 ctx.beginPath();ctx.roundRect(390,486,180,34,3);ctx.fillStyle='#1c2020';ctx.fill();ctx.fillStyle='#414640';ctx.fillRect(402,492,156,1);ctx.fillStyle='#d9f36a';ctx.fillRect(414,502,5,3);ctx.fillStyle='#d86c54';ctx.fillRect(426,502,5,3);ctx.fillStyle='#d9f36a';ctx.fillRect(438,502,5,3);ctx.fillStyle='#a4aaa0';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText('LANCIA  ·  4WD',480,515);ctx.beginPath();ctx.ellipse(480,557,143,83,0,Math.PI,Math.PI*2);ctx.strokeStyle='#090b0b';ctx.lineWidth=18;ctx.stroke();ctx.beginPath();ctx.ellipse(480,557,143,83,0,Math.PI,Math.PI*2);ctx.strokeStyle='#4b4d48';ctx.lineWidth=2;ctx.stroke();polygon([[467,495],[493,495],[516,536],[504,540],[480,517],[456,540],[444,536]],'#343936');ctx.restore();}
function render(){ctx.clearRect(0,0,W,H);drawSky();drawTerrain();drawHeadlights();for(const r of racers)drawRacer(r);drawCockpit();if(state.speed>75){ctx.globalAlpha=Math.min(.24,(state.speed-75)/160);ctx.strokeStyle='#c7c9ae';ctx.lineWidth=1;for(let i=0;i<7;i++){const x=hash(i+Math.floor(state.time*9)),y=HORIZON+120+hash(i+88)*250;ctx.beginPath();ctx.moveTo(x*W,y);ctx.lineTo(x*W+(x<.5?-1:1)*12,y+30);ctx.stroke();}ctx.globalAlpha=1;}}

