function render(){ctx.clearRect(0,0,W,H);drawSky();drawTerrain();drawHeadlights();for(const r of racers)drawRacer(r);drawCockpit();if(state.speed>75){ctx.globalAlpha=Math.min(.24,(state.speed-75)/160);ctx.strokeStyle='#c7c9ae';ctx.lineWidth=1;for(let i=0;i<7;i++){const x=hash(i+Math.floor(state.time*9)),y=HORIZON+120+hash(i+88)*250;ctx.beginPath();ctx.moveTo(x*W,y);ctx.lineTo(x*W+(x<.5?-1:1)*12,y+30);ctx.stroke();}ctx.globalAlpha=1;}}
function formatTime(seconds){const m=Math.floor(seconds/60),s=seconds%60;return`${String(m).padStart(2,'0')}:${s.toFixed(2).padStart(5,'0')}`;}
function updateHud(){const remaining=Math.max(0,FINISH-state.dist);ui.speed.textContent=String(Math.round(state.speed)).padStart(3,'0');ui.gear.textContent=state.speed<3?'N':String(Math.min(6,Math.max(1,Math.floor(state.speed/28)+1)));ui.distance.textContent=(remaining/1000).toFixed(1);ui.progress.style.width=`${Math.min(100,state.dist/FINISH*100)}%`;ui.clock.textContent=formatTime(state.time);ui.surface.textContent=Math.abs(state.lane)>145?'SOFT VERGE':state.speed>120?'LOOSE':'GRAVEL';if(state.calloutUntil>state.time){ui.callout.textContent=state.callout;ui.callout.parentElement.style.opacity='1';}else ui.callout.parentElement.style.opacity='.32';}
function showCallout(text,duration=2.2){state.callout=text;state.calloutUntil=state.time+duration;}
function setControl(name,on){if(name==='left')state.keys.ArrowLeft=on;else if(name==='right')state.keys.ArrowRight=on;else if(name==='accelerate')state.accelerate=on;else if(name==='brake')state.brake=on;}
function resetGame(){state.running=false;state.done=false;state.dist=0;state.speed=0;state.lane=0;state.laneVelocity=0;state.time=0;state.shake=0;state.callout='NIGHT STAGE · GRAVEL';state.calloutUntil=2.5;racers[0].at=540;racers[1].at=1060;racers[2].at=1830;racers.forEach((r,i)=>r.at=[540,1060,1830][i]);ui.result.classList.add('hidden');$('introCard').classList.remove('hidden');ui.overlay.classList.remove('dismissed');$('finalTime').textContent='00:00.00';ui.distance.textContent='4.2';ui.progress.style.width='0%';}
function finishGame(){state.running=false;state.done=true;$('finalTime').textContent=formatTime(state.time);$('resultTitle').innerHTML=state.time<60?'FLYING<br><em>FINN</em>':state.time<90?'NIGHT<br><em>DRIVER</em>':'STAGE<br><em>SURVIVOR</em>';ui.result.classList.remove('hidden');$('introCard').classList.add('hidden');ui.overlay.classList.remove('dismissed');showCallout('STAGE COMPLETE',5);}
function update(dt){if(!state.running)return;state.time+=dt;state.keys.ArrowUp=state.keys.ArrowUp||state.keys.KeyW;state.keys.ArrowDown=state.keys.ArrowDown||state.keys.KeyS;const throttle=state.accelerate||state.keys.ArrowUp,braking=state.brake||state.keys.ArrowDown;const offroad=Math.abs(state.lane)>135;const target=throttle?174:0;state.speed+=((target-state.speed)*(throttle?.42:.14))*dt;if(braking)state.speed=Math.max(0,state.speed-125*dt);if(offroad)state.speed=Math.max(0,state.speed-24*dt);state.speed=clamp(state.speed,0,174);const steer=(state.keys.ArrowRight||state.keys.KeyD?1:0)-(state.keys.ArrowLeft||state.keys.KeyA?1:0);state.steer+=(steer-state.steer)*Math.min(1,dt*8);state.laneVelocity+=state.steer*(52+state.speed*.68)*dt;state.laneVelocity*=Math.pow(.12,dt);state.lane+=state.laneVelocity*dt;state.lane=clamp(state.lane,-205,205);state.shake+=(offroad?Math.min(4,(Math.abs(state.lane)-125)*.12):0-state.shake)*Math.min(1,dt*7);state.dist+=state.speed/3.6*dt;for(const r of racers){r.at+=r.speed/3.6*dt;if(Math.abs(r.at-state.dist)<18&&Math.abs(state.lane-r.lane*150)<47){state.speed=Math.max(18,state.speed-70*dt);state.shake=Math.max(state.shake,3);}}const left=Math.floor(state.dist/350),previous=Math.floor((state.dist-state.speed/3.6*dt)/350);if(left>previous){const curve=curveAt(state.dist+180);showCallout(Math.abs(curve)>.45?(curve>0?'TIGHT RIGHT · 150':'TIGHT LEFT · 150'):(curve>0?'RIGHT · 150':'LEFT · 150'));}if(state.dist>=FINISH){state.dist=FINISH;finishGame();}updateHud();}
let lastFrame=performance.now();function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;update(dt);render();requestAnimationFrame(frame);}requestAnimationFrame(frame);
function startGame(){if(state.done)resetGame();state.running=true;state.last=performance.now();state.calloutUntil=state.time+2.5;ui.overlay.classList.add('dismissed');$('introCard').classList.add('hidden');if(state.sound&&window.AudioContext){try{if(!state.engine){const audio=new AudioContext(),osc=audio.createOscillator(),gain=audio.createGain();osc.type='sawtooth';gain.gain.value=.012;osc.connect(gain);gain.connect(audio.destination);osc.start();state.engine={audio,osc,gain};}state.engine.audio.resume();}catch(e){}}}
$('startButton').addEventListener('click',startGame);$('restartButton').addEventListener('click',resetGameAndStart);function resetGameAndStart(){resetGame();startGame();}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();state.keys[e.code]=true;if(e.code==='Enter'&&!state.running&&!state.done)startGame();});window.addEventListener('keyup',e=>{state.keys[e.code]=false;});window.addEventListener('blur',()=>{state.keys={};state.accelerate=false;state.brake=false;});
document.querySelectorAll('.mobile-controls button').forEach(button=>{const name=button.dataset.control;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);setControl(name,true);});for(const event of['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,()=>setControl(name,false));});
$('soundButton').addEventListener('click',()=>{state.sound=!state.sound;$('soundButton').innerHTML=`<span class="sound-icon">${state.sound?'♪':'×'}</span><span>SOUND <b>${state.sound?'ON':'OFF'}</b></span>`;if(state.engine){state.engine.gain.gain.value=state.sound?.012:0;if(state.sound)state.engine.audio.resume();}});
updateHud();render();
})();

